/* AXIS 토큰: 기본 CSS 변수(--axis-*)와 shadcn 호환 변수(--background · --primary 등). @import 는 @tailwind 보다 앞에 둡니다 */
@import "@axis-ds/tokens/css";
@import "@axis-ds/tokens/css/shadcn";
/* ontology 브랜드: 아래 줄의 주석을 풀고 app/layout.tsx 의 <html> 에 data-brand="ontology" 를 넣습니다 */
/* @import "@axis-ds/tokens/css/brands/ontology"; */

@tailwind base;
@tailwind components;
@tailwind utilities;

/*
 * 테두리 기본색: Tailwind 3 preflight 의 `* { border-color: gray-200 }` 가 shadcn 호환 CSS 의 `* { border-color }` 보다
 * 뒤에 와서 이기므로, `border` 클래스가 다크 · 브랜드에서도 회색으로 남지 않게 AXIS --border 로 되돌립니다
 */
@layer base {
  * {
    @apply border-border;
  }
}

import type { Metadata } from 'next'
// AXIS 대표 글꼴 Pretendard(동적 서브셋). 글꼴 스택은 AXIS preset 이 <html> 에 적용합니다
import 'pretendard/dist/web/variable/pretendardvariable-dynamic-subset.css'
import './globals.css'

export const metadata: Metadata = {
  title: 'AXIS Landing Page',
  description: 'AXIS 디자인 시스템 기반 랜딩 페이지',
}

// ontology 브랜드를 켜려면 globals.css 의 브랜드 import 주석을 풀고 <html> 에 data-brand="ontology" 를 넣습니다
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="ko" suppressHydrationWarning>
      <body>{children}</body>
    </html>
  )
}

import { Hero } from '../components/hero'

const features = [
  {
    title: '디자인 토큰',
    description: 'CSS 변수 기반으로 일관된 스타일을 유지합니다.',
  },
  {
    title: '다크모드',
    description: '시스템 설정과 연동되는 다크모드를 지원합니다.',
  },
  {
    title: '반응형 레이아웃',
    description: '모바일부터 데스크톱까지 최적화된 레이아웃을 제공합니다.',
  },
  {
    title: '접근성',
    description: 'WCAG 2.1 AA 기준을 충족하는 컴포넌트를 사용합니다.',
  },
]

export default function Home() {
  return (
    <main className="min-h-screen bg-background text-foreground">
      <Hero />

      <section className="py-16 px-6 max-w-5xl mx-auto">
        <h2 className="text-2xl font-bold text-center mb-10">주요 기능</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
          {features.map((feature) => (
            <div
              key={feature.title}
              className="rounded-lg border bg-card p-6 text-card-foreground"
            >
              <h3 className="font-semibold text-lg mb-2">{feature.title}</h3>
              <p className="text-sm text-muted-foreground">{feature.description}</p>
            </div>
          ))}
        </div>
      </section>

      <footer className="border-t py-8 text-center text-sm text-muted-foreground">
        Built with AXIS Design System
      </footer>
    </main>
  )
}

/** Tailwind 3 를 PostCSS 플러그인으로 돌립니다(없으면 @tailwind 지시문이 그대로 남아 유틸리티가 생성되지 않음, WI-0037) */
export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

import type { Config } from 'tailwindcss'
import axisPreset from '@axis-ds/tokens/tailwind'

/** 색 · 둥글기 · 글꼴(Pretendard 스택) · darkMode 는 AXIS preset 이 정합니다 */
const config: Config = {
  presets: [axisPreset],
  content: ['./app/**/*.{ts,tsx}', './components/**/*.{ts,tsx}'],
  plugins: [],
}

export default config
